+export type PickSimilarityDimension =
+  | "adp_at_pick"
+  | "position"
+  | "player_age"
+  | "target_share_pct"
+  | "snap_pct"
+  | "team_offensive_rank"
+  | "injury_history"
+  | "new_coordinator"
+  | "contract_year";
+
+export interface HistoricalPickQuery {
+  position: string;
+  pickRound: number;
+  adpValue: number;
+  teamOffensiveRank: number | null;
+  playerAge: number | null;
+  hasNewCoordinator: boolean;
