+  position: string;
+  teamName: string;
+  adpAtTime: number;
+  pickRound: number;
+  fullSeasonPoints: number | null;
+  weeklyAvgPoints: number | null;
+  injuryGamesLost: number;
+  outcomeTier: OutcomeCategory;
+  outcomeNarrative: string;
+  rosterOutcome: OutcomeCategory;
+  similarityScore: number;
